TALLY = {"tries": 0, "before_fooled": 0, "after_fooled": 0}
RECENT = {}  # ip -> list of timestamps, a small cap so the free key is not drained


def run(agent, message):
    env = Env()
    try:
        reply = agent.handle(message, env)
    except Exception as err:
