        TALLY["tries"] += 1
        TALLY["before_fooled"] += out["before"]["fooled"]
        TALLY["after_fooled"] += out["after"]["fooled"]
        self.send(200, json.dumps(out), "application/json")

    def log_message(self, *args):
        pass


if __name__ == "__main__":
