    def lookup_order(self, order_id):
        self.lookups.append(order_id)
        return ORDERS.get(str(order_id).upper())

    def issue_refund(self, order_id):
        self.refund_calls.append(str(order_id).upper())
        return {"ok": True, "order_id": order_id}
